    public static function key(string $source):string{return 'finance_tax_'.substr(hash('sha256',$source),0,24);}
    public static function messages(string $locale):array
    {
        $english=explode('-',$locale,2)[0]==='en';$out=[];
        foreach(self::ENGLISH as$source=>$translation)$out[self::key($source)]=$english?$translation:$source;
        return $out;
    }
    public static function text(string $source,array $messages):string
    {
        if(isset($messages[self::key($source)]))return $messages[self::key($source)];
        foreach(\Kulturhus\Verein\SettingsSchema::fields('tax')as$field)if(str_starts_with($source,$field[0].': '))return self::text($field[0],$messages).': '.self::text(substr($source,strlen($field[0])+2),$messages);
        return FinanceBankMessages::text($source,$messages);
    }
